script:
(function () {
  'use strict';
  // Four-function calculator with immediate (left-to-right) execution, like a desk calculator.
  // The arithmetic is done directly on numbers (no eval/new Function). Each result is rounded to
  // 12 significant digits to remove binary floating-point noise.
  // Checked under Node (scratchpad/tests/b7basic/bc_test.js, 27 key sequences): 0.1 + 0.2 = 0.3,
  // 1 / 3 = 0.333333333333, 2 + 3 x 4 = 20 (left to right), 2 + 3 = = gives 8 (repeat), 5 x = gives 25,
  // 1 / 0 shows an error, 200 + 10% = 220, 50 x 20% = 10, 1.1 x 1.1 = 1.21, 0.3 - 0.1 = 0.2,
  // M+ / M- / MR / MC, sign change, backspace and thousands grouping.
  // ---- Calculator engine (no DOM; arithmetic done directly, never eval) ----
  var MAX_DIGITS = 15;
  var SYMBOL = { '+': '+', '-': '−', '*': '×', '/': '÷' };

  // Round to 12 significant digits so 0.1 + 0.2 shows 0.3, not 0.30000000000000004.
  function clean(x) {
    if (!isFinite(x)) return x;
    var r = parseFloat(x.toPrecision(12));
    return r === 0 ? 0 : r; // drop -0
  }

  function apply(a, op, b) {
    if (op === '+') return clean(a + b);
    if (op === '-') return clean(a - b);
    if (op === '*') return clean(a * b);
    if (b === 0) return NaN; // divide by zero
    return clean(a / b);
  }

  function group(intPart) {
    return intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  }

  // Display text for a finished number.
  function fmt(x) {
    if (x === 0) return '0';
    var ax = Math.abs(x);
    if (ax >= 1e15 || ax < 1e-9) {
      var e = x.toExponential(10).replace(/\.?0+e/, 'e');
      return e.replace('e+', 'e');
    }
    var s = String(x);
    if (s.indexOf('e') !== -1) s = x.toFixed(12).replace(/\.?0+$/, '');
    var neg = s.charAt(0) === '-';
    if (neg) s = s.slice(1);
    var parts = s.split('.');
    return (neg ? '−' : '') + group(parts[0]) + (parts.length > 1 ? '.' + parts[1] : '');
  }

  // Display text for a number being typed (keeps a trailing point or zeros).
  function fmtEntry(s) {
    var neg = s.charAt(0) === '-';
    if (neg) s = s.slice(1);
    var i = s.indexOf('.');
    var intPart = i === -1 ? s : s.slice(0, i);
    return (neg ? '−' : '') + group(intPart) + (i === -1 ? '' : s.slice(i));
  }

  function toEntry(x) {
    // Raw (ungrouped) string for a number, used when a result becomes the next entry.
    var s = String(x);
    if (s.indexOf('e') !== -1 && Math.abs(x) < 1e15 && Math.abs(x) >= 1e-9) s = x.toFixed(12).replace(/\.?0+$/, '');
    return s;
  }

  function createEngine() {
    var st;
    function reset() {
      st = { entry: '0', acc: null, op: null, waiting: false, fresh: true, error: '',
             expr: '', lastOp: null, lastB: null, justEvaluated: false, mem: st ? st.mem : 0, tape: st ? st.tape : [] };
    }
    st = null; reset();

    function value() { var v = parseFloat(st.entry); return isNaN(v) ? 0 : v; }
    function setResult(x) {
      if (!isFinite(x)) {
        var msg = isNaN(x) ? 'Can’t divide by zero' : 'Number too large';
        reset(); st.error = msg; return false;
      }
      st.entry = toEntry(x); st.fresh = true; return true;
    }
    function clearErrorIfAny() { if (st.error) reset(); }

    var api = {
      digit: function (d) {
        clearErrorIfAny();
        if (st.justEvaluated) { st.expr = ''; st.justEvaluated = false; st.lastOp = null; }
        if (st.fresh) { st.entry = '0'; st.fresh = false; }
        st.waiting = false;
        var digits = st.entry.replace(/[^0-9]/g, '').length;
        if (st.entry === '0') st.entry = d;
        else if (st.entry === '-0') st.entry = '-' + d;
        else if (digits < MAX_DIGITS) st.entry += d;
      },
      dot: function () {
        clearErrorIfAny();
        if (st.justEvaluated) { st.expr = ''; st.justEvaluated = false; st.lastOp = null; }
        if (st.fresh) { st.entry = '0.'; st.fresh = false; st.waiting = false; return; }
        st.waiting = false;
        if (st.entry.indexOf('.') === -1) st.entry += '.';
      },
      op: function (o) {
        if (st.error) return;
        st.justEvaluated = false; st.lastOp = null;
        if (st.op && !st.waiting) {
          var r = apply(st.acc, st.op, value());
          if (!setResult(r)) return;
          st.acc = r;
        } else if (!st.op) {
          st.acc = value();
        }
        st.op = o; st.waiting = true; st.fresh = true;
        st.entry = toEntry(st.acc);
        st.expr = fmt(st.acc) + ' ' + SYMBOL[o];
      },
      equals: function () {
        if (st.error) return;
        var a, b, op;
        if (st.op) {
          a = st.acc; op = st.op; b = st.waiting ? st.acc : value();
        } else if (st.lastOp && st.justEvaluated) {
          a = value(); op = st.lastOp; b = st.lastB;
        } else {
          return;
        }
        var r = apply(a, op, b);
        var line = fmt(a) + ' ' + SYMBOL[op] + ' ' + fmt(b) + ' =';
        st.op = null; st.acc = null; st.waiting = false;
        if (!setResult(r)) return;
        st.expr = line; st.lastOp = op; st.lastB = b; st.justEvaluated = true;
        st.tape.unshift(line + ' ' + fmt(r));
        if (st.tape.length > 10) st.tape.length = 10;
      },
      percent: function () {
        if (st.error) return;
        var x = value();
        // With + or − pending, x% means x percent of the first number (200 + 10% = 220);
        // otherwise it is x ÷ 100 (50 × 20% = 10).
        var r = (st.op === '+' || st.op === '-') ? clean(st.acc * x / 100) : clean(x / 100);
        if (!setResult(r)) return;
        st.waiting = false; st.justEvaluated = false;
      },
      sign: function () {
        if (st.error) return;
        if (st.waiting) { st.entry = toEntry(st.acc); st.waiting = false; st.fresh = true; }
        if (st.fresh) {
          var v = value();
          st.entry = toEntry(v === 0 ? 0 : -v);
          if (st.justEvaluated) { st.justEvaluated = false; st.lastOp = null; st.expr = ''; }
          return;
        }
        st.entry = st.entry.charAt(0) === '-' ? st.entry.slice(1) : '-' + st.entry;
      },
      back: function () {
        if (st.error) { reset(); return; }
        if (st.fresh || st.waiting) { if (st.justEvaluated) { st.expr = ''; st.justEvaluated = false; st.lastOp = null; } return; }
        st.entry = st.entry.slice(0, -1);
        if (st.entry === '' || st.entry === '-') st.entry = '0';
      },
      clear: function () { reset(); },
      mc: function () { st.mem = 0; },
      mr: function () {
        clearErrorIfAny();
        st.entry = toEntry(st.mem); st.fresh = true; st.waiting = false;
        if (st.justEvaluated) { st.expr = ''; st.justEvaluated = false; st.lastOp = null; }
      },
      mplus: function () { if (st.error) return; st.mem = clean(st.mem + value()); st.fresh = true; },
      mminus: function () { if (st.error) return; st.mem = clean(st.mem - value()); st.fresh = true; },
      state: function () {
        return {
          screen: st.error ? st.error : (st.fresh || st.waiting ? fmt(value()) : fmtEntry(st.entry)),
          expr: st.error ? '' : st.expr,
          error: !!st.error,
          mem: st.mem,
          memText: fmt(st.mem),
          tape: st.tape.slice()
        };
      }
    };
    return api;
  }

  // ---- Page wiring ----
  var KEYMAP = { '0': ['digit', '0'], '1': ['digit', '1'], '2': ['digit', '2'], '3': ['digit', '3'], '4': ['digit', '4'],
    '5': ['digit', '5'], '6': ['digit', '6'], '7': ['digit', '7'], '8': ['digit', '8'], '9': ['digit', '9'],
    '.': ['dot'], ',': ['dot'], '+': ['op', '+'], '-': ['op', '-'], '*': ['op', '*'], 'x': ['op', '*'], 'X': ['op', '*'],
    '/': ['op', '/'], '%': ['percent'], 'Enter': ['equals'], '=': ['equals'], 'Escape': ['clear'], 'Delete': ['clear'],
    'Backspace': ['back'] };

  document.addEventListener('DOMContentLoaded', function () {
    var root = document.getElementById('bcCalc');
    if (!root) return;
    var calc = createEngine();
    var screen = document.getElementById('bcScreen'), expr = document.getElementById('bcExpr'),
        memFlag = document.getElementById('bcMemFlag'), memValue = document.getElementById('bcMemValue'),
        tape = document.getElementById('bcTape'), tapeEmpty = document.getElementById('bcTapeEmpty');

    function render() {
      var s = calc.state();
      screen.textContent = s.screen;
      screen.className = s.error
        ? 'mt-1 block min-h-11 py-2 font-body text-base font-semibold text-blush-ink'
        : 'mt-1 block min-h-11 break-all font-readout text-4xl font-semibold tabular-nums leading-tight';
      expr.textContent = s.expr || ' ';
      memFlag.hidden = s.mem === 0;
      memValue.textContent = s.memText;
      while (tape.firstChild) tape.removeChild(tape.firstChild);
      s.tape.forEach(function (line) {
        var li = document.createElement('li');
        li.className = 'border-b border-line pb-2 last:border-0 last:pb-0';
        li.textContent = line;
        tape.appendChild(li);
      });
      tapeEmpty.hidden = s.tape.length > 0;
    }

    function run(act, val) {
      if (typeof calc[act] !== 'function' || act === 'state') return;
      calc[act](val);
      render();
    }

    root.addEventListener('click', function (e) {
      var btn = e.target.closest ? e.target.closest('button[data-act]') : null;
      if (!btn || !root.contains(btn)) return;
      run(btn.getAttribute('data-act'), btn.getAttribute('data-val'));
    });

    function flash(key) {
      var btn = root.querySelector('button[data-key="' + (key === ',' ? '.' : key === 'x' || key === 'X' ? '*' : key === '=' ? 'Enter' : key === 'Delete' ? 'Escape' : key) + '"]');
      if (!btn) return;
      btn.classList.add('calc-key-pressed');
      setTimeout(function () { btn.classList.remove('calc-key-pressed'); }, 120);
    }

    // Typing works when focus is on the calculator, or nowhere in particular on the page.
    document.addEventListener('keydown', function (e) {
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      var t = e.target;
      var inside = root.contains(t);
      if (!inside && t !== document.body && t !== document.documentElement) return;
      var m = KEYMAP[e.key];
      if (!m) return;
      e.preventDefault(); // stops Enter re-clicking a focused key and "/" opening quick find
      flash(e.key);
      run(m[0], m[1]);
    });

    render();
  });
})();
